INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 2834, 2, 40, 7, 20063115, 91002, "ペコリーヌとの出会い", "フリーマーケット会場", 10118, 1, "青空の下で謁見", 0, 5118061, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 2835, 2, 40, 7, 20063115, 91002, "マホとの出会い", "フリーマーケット会場", 10118, 1, "未来の騎空団\nマスコット？", 0, 5118062, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 2837, 2, 40, 7, 20063115, 91002, "アキノとの出会い", "ランドソル市街地", 10118, 1, "お嬢さまからの\n緊急依頼", 0, 5118063, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4108402, 2, 40, 18, 20063115, 91002, "ジュンとの出会い", "フリーマーケット会場", 10118, 1, "黄金色の悩みごと", 0, 5118064, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4107402, 2, 40, 18, 20063115, 91002, "カオリとの出会い", "フリーマーケット会場", 10118, 1, "白熱！　格闘大会！", 0, 5118065, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 9000227, 2, 40, 16, 20063115, 91002, "ニノンとの出会い", "オーエド町", 10118, 1, "祭り太鼓はオーエドの華", 1, 5118066, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 2101181, 3, 40, 19, 20063115, 91002, "スズナとの出会い", "フリーマーケット会場", 10118, 1, "人気者は遅れて\nやってくる", 0, 5118067, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4109402, 3, 40, 18, 20063115, 91002, "ナナカとの出会い", "ランドソル市街地", 10118, 1, "巫女・ミーツ・魔法少女", 0, 5118068, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4305402, 3, 40, 18, 20063115, 91002, "キャル＆コッコロとの出会い", "フリーマーケット会場", 10118, 1, "ネズ耳は二度なくなる", 0, 5118069, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4101402, 3, 40, 18, 20063115, 91002, "ユカリとの出会い", "ランドソル市街地", 10118, 1, "この出会いにカンパイ！", 0, 5118070, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 4106402, 3, 40, 18, 20063115, 91002, "アオイとの出会い", "ランドソル市街地", 10118, 1, "陰陽アンサンブル", 0, 5118071, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (8, 2836, 3, 40, 7, 20063115, 91002, "シノブとの出会い", "フリーマーケット会場", 10118, 1, "運試し十番勝負！", 1, 5118072, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (0, 0, 1, 0, 0, 20063115, 0, "オープニング", 0, 10118, 0, "彼女たちの新たな日常", 0, 5118600, 0);
